import torch


def run_correctness(x, n):
    ref_n = n.to(torch.float32) if torch.is_tensor(n) else n
    output = torch.special.shifted_chebyshev_polynomial_u(x.float(), ref_n)
    return output.to(x.dtype)


def run(x, n):
    return torch.special.shifted_chebyshev_polynomial_u(x, n)


def gen_inputs(ctx, device):
    out = {}
    if "x__shape" in ctx:
        out["x"] = torch.rand(ctx["x__shape"], dtype=torch.float32, device=device)
    if "n__shape" in ctx:
        out["n"] = torch.randint(0, 10, ctx["n__shape"], dtype=torch.long, device=device)
    return out
